let gems;
const toSlow = false;

function setup() {
	const minWH = min(innerWidth, innerHeight)
	createCanvas(innerWidth, innerHeight);
	describe("rotating gems with different shapes and palettes");
	pixelDensity(1);
	frameRate(30);

	gems = [];
	if (toSlow) {
		gems.push(new Gem(0, 0, minWH * 0.9));
	} else {
		gems.push(new Gem(minWH * -0.25, minWH * -0.25, minWH * 0.45));
		gems.push(new Gem(minWH * 0.25, minWH * -0.25, minWH * 0.45));
		gems.push(new Gem(minWH * -0.25, minWH * 0.25, minWH * 0.45));
		gems.push(new Gem(minWH * 0.25, minWH * 0.25, minWH * 0.45));
	}

	// // noLoop() removed for animation
}

function draw() {
	background((sin(frameCount*0.01)+1)*128);
	translate(width * 0.5, height * 0.5)
	for (let gem of gems) {
		gem.show();
	}
}

function drawBack() {
	push();
	translate(width*0.3, height*0.35);
	rotate(-0.5)
	translate(-width*0.3, -height*0.35);
	noStroke();
	fill("silver")
	for (let i = 0; i < 6; i++) {
		let x = (noise(frameCount * 0.0013 + i) - 0.5) * width;
		let y = noise(frameCount * 0.0012 + i) * height;
		let w = noise(frameCount * 0.000623 + i) * width;
		let h = noise(frameCount * 0.000532 + i) * height * 0.25;
		rect(x, y, w, h)
	}
	pop();
}

function mousePressed() {
	if (mouseButton === LEFT) setup();
}

class Gem {
	constructor(x, y, s) {
		this.x = x;
		this.y = y;
		this.s = s;
		this.a = 0;

		const pals = [
			["red", "darkgreen", "navy", "darkred", "yellow"],
			["blue", "lightblue", "cyan", "pink"],
			["rgb(38,38,58)", "white"],
			["rgb(58,38,38)", "white"],
		];
		this.pal = random(pals)

		const num = random(12, 20);
		const r = this.s * 0.5;
		// define points
		this.pts = [];

		// randomly choose gem style
		if (random() < 0.5) {
			// circle
			for (let i = 0; i < num; i++) {
				const a = random(TWO_PI)
				var x = cos(a) * r;
				var y = sin(a) * r;
				this.pts.push({x, y});
			}

		} else {
			// rectangle
			this.pts.push({x: this.s * 0.35, y: this.s * -0.35});
			this.pts.push({x: this.s * 0.35, y: this.s * 0.35});
			this.pts.push({x: this.s * -0.35, y: this.s * 0.35});
			this.pts.push({x: this.s * -0.35, y: this.s * -0.35});
			this.pts.push({x: this.s * 0.25, y: this.s * -0.45});
			this.pts.push({x: this.s * 0.25, y: this.s * 0.45});
			this.pts.push({x: this.s * -0.25, y: this.s * 0.45});
			this.pts.push({x: this.s * -0.25, y: this.s * -0.45});
			// hard coded 8 initial points
			for (let i = this.pts.length; i < num; i++) {
				let pi = floor(random(8));
				let pn = (pi + 1) % 8;
				const fr = random(0.2, 0.8)
				var x = lerp(this.pts[pi].x, this.pts[pn].x, fr);
				var y = lerp(this.pts[pi].y, this.pts[pn].y, fr);
				this.pts.push({x, y});
			}
		}

		// calculate vertexes of points
		this.vtx = [];
		const pl = this.pts.length;
		for (let i = 0; i < pl - 2; i++) {
			for (let j = i + 1; j < pl - 1; j++) {
				const k =  j + 1; //floor(random(j + 1, pl - 1))
				// for (let k = j + 1; k < pl; k++) {
					const c = floor(random(this.pal.length));
					this.vtx.push({i, j, k, c});
				// }
			}
		}

		// console.log("gem: pts:" + pl + ", vertexes:" + this.vtx.length);
	}

	show() {
		push();
		translate(this.x, this.y);
		this.a += 0.01;
		rotate(this.a)

		noFill();
		strokeWeight(1);
		stroke(32);

		noStroke();
		blendMode(DIFFERENCE)

		for (let v of this.vtx) {
			fill(this.pal[v.c])
			triangle(
				this.pts[v.i].x, this.pts[v.i].y, 
				this.pts[v.j].x, this.pts[v.j].y, 
				this.pts[v.k].x, this.pts[v.k].y
			)
		}

		// swap vertexes
		if (random() < 0.1) {
			// shuffle(this.vtx, true);
			this.vtx.push(this.vtx.shift())
			/*
			const vtxLen = this.vtx.length;
			const vtxA = floor(random(vtxLen));
			const vtxB = floor(random(vtxLen));
			const tmp = this.vtx[vtxB];
			this.vtx[vtxB] = this.vtx[vtxA];
			this.vtx[vtxA] = tmp;
			*/
		}


		pop();
	}
}

